    describe('Comprehensive Field Coverage', () => {
        describe('Fluent to XML - All Fields', () => {
            test('Create record producer with all fields', async () => {
                const project = createProject({ config: { scope: SCOPE } })

                const recordProducerId = project.registerCoalesceId('sc_cat_item_producer', {
                    name: 'Comprehensive Test Record Producer',
                })

                // Register all M2M relationships
                project.registerCoalesceId('sc_cat_item_catalog', {
                    sc_cat_item: recordProducerId,
                    sc_catalog: 'catalog-id',
                })

                project.registerCoalesceId('sc_cat_item_category', {
                    sc_cat_item: recordProducerId,
                    sc_category: 'category-id',
                })

                project.registerCoalesceId('io_set_item', {
                    sc_cat_item: recordProducerId,
                    variable_set: 'varset-id',
                })

                project.registerCoalesceId('sc_cat_item_user_criteria_mtom', {
                    sc_cat_item: recordProducerId,
                    user_criteria: 'available-for-id',
                })

                project.registerCoalesceId('sc_cat_item_user_criteria_no_mtom', {
                    sc_cat_item: recordProducerId,
                    user_criteria: 'not-available-for-id',
                })

                project.registerCoalesceId('m2m_connected_content', {
                    catalog_item: recordProducerId,
                    topic: 'topic-id',
                })

                const file = project.addFile({
                    path: 'comprehensive.now.ts',
                    content: CODE_COMPREHENSIVE,
                })

                const output = await file.getOutput()

                // Should create 1 main record + 6 M2M records (no pricingDetails) = 7 total
                expect(output).toHaveLength(7)

                // Find the main record producer XML
                const recordProducerXml = output.find((o) => o.path.includes('sc_cat_item_producer'))
                expect(recordProducerXml).toBeDefined()

                // Verify Record Producer specific fields
                expect(recordProducerXml!.content).toContain('<table_name>incident</table_name>')
                expect(recordProducerXml!.content).toContain('<![CDATA[// BEFORE script')
                expect(recordProducerXml!.content).toContain('<![CDATA[// AFTER script')
                expect(recordProducerXml!.content).toContain('<![CDATA[// SAVE script')
                expect(recordProducerXml!.content).toContain('<redirect_url>generated_record</redirect_url>')
                expect(recordProducerXml!.content).toContain('<view>ess</view>')
                expect(recordProducerXml!.content).toContain('<allow_edit>true</allow_edit>')
                expect(recordProducerXml!.content).toContain('<can_cancel>true</can_cancel>')
                expect(recordProducerXml!.content).toContain('<save_options>connect</save_options>')

                // Verify Basic Information fields
                expect(recordProducerXml!.content).toContain('<name>Comprehensive Test Record Producer</name>')
                expect(recordProducerXml!.content).toContain(
                    '<short_description>Testing all fields</short_description>'
                )
                expect(recordProducerXml!.content).toContain('<order>500</order>')

                // Verify Access Control fields
                expect(recordProducerXml!.content).toContain('<availability>on_both</availability>')

                // Verify Form Behavior
                expect(recordProducerXml!.content).toContain(
                    '<show_variable_help_on_load>true</show_variable_help_on_load>'
                )

                // Verify Advanced fields
                expect(recordProducerXml!.content).toContain('<owner>owner-id</owner>')
            })
        })

        describe('XML to Fluent - Supported Fields', () => {
            test('Parse record producer XML with supported fields', async () => {
                const project = createProject({ rootDir: __dirname })

                const output = await project.transform(['../xml/record-producer/sc_cat_item_producer.xml'])

                // Find the .now.ts file (excludes generated keys.ts)
                const fluentFile = output.changedFiles.find((f) => f.getName().endsWith('.now.ts'))
                expect(fluentFile).toBeDefined()

                const fluentCode = fluentFile!.getContent()

                // Verify Record Producer specific fields
                expect(fluentCode).toContain("table: 'task'")

                // Verify Basic Information
                expect(fluentCode).toContain("name: 'Record producer test'")
                expect(fluentCode).toContain("shortDescription: 'Record producer test'")
                expect(fluentCode).toContain('order: 100')
            })
        })

        describe('Fluent => XML => Fluent - Supported Fields Round-Trip', () => {
            test('Supported fields round-trip correctly', async () => {
                const project = createProject({ config: { scope: SCOPE } })
                const test = new FluentXmlFluentTest(project)

                const recordProducerId = test.addId('sc_cat_item_producer', 'comprehensive_test_record_producer')

                // Register all M2M relationships
                const catalogId = test.addCoalesceId('sc_cat_item_catalog', {
                    sc_cat_item: recordProducerId,
                    sc_catalog: 'catalog-id',
                })

                const categoryId = test.addCoalesceId('sc_cat_item_category', {
                    sc_cat_item: recordProducerId,
                    sc_category: 'category-id',
                })

                const varsetId = test.addCoalesceId('io_set_item', {
                    sc_cat_item: recordProducerId,
                    variable_set: 'varset-id',
                })

                const availableForId = test.addCoalesceId('sc_cat_item_user_criteria_mtom', {
                    sc_cat_item: recordProducerId,
                    user_criteria: 'available-for-id',
                })

                const notAvailableForId = test.addCoalesceId('sc_cat_item_user_criteria_no_mtom', {
                    sc_cat_item: recordProducerId,
                    user_criteria: 'not-available-for-id',
                })

                const topicId = test.addCoalesceId('m2m_connected_content', {
                    catalog_item: recordProducerId,
                    topic: 'topic-id',
                })

                test.addExpectedXmlFileNames(
                    `sc_cat_item_producer_${recordProducerId}.xml`,
                    `sc_cat_item_catalog_${catalogId}.xml`,
                    `sc_cat_item_category_${categoryId}.xml`,
                    `io_set_item_${varsetId}.xml`,
                    `sc_cat_item_user_criteria_mtom_${availableForId}.xml`,
                    `sc_cat_item_user_criteria_no_mtom_${notAvailableForId}.xml`,
                    `m2m_connected_content_${topicId}.xml`
                )

                test.addFluentFragment(CODE_COMPREHENSIVE)

                await test.verify()
            })
        })
    })
